const $=s=>document.querySelector(s),canvas=$('#field'),status=$('#status'),ctx=canvas.getContext('2d');
const snapshot=StoryProgressionService.prototype.snapshot,storyBusy=Object.getOwnPropertyDescriptor(StoryProgressionService.prototype,'busy').get,pending=Object.getOwnPropertyDescriptor(StoryProgressionService.prototype,'pendingCommit').get,abortRead=Object.getOwnPropertyDescriptor(AbortSignal.prototype,'aborted').get;
const invoke=(fn,target)=>Reflect.apply(fn,target,[]),readSnapshot=b=>invoke(snapshot,b.story),aborted=signal=>invoke(abortRead,signal);
