const lifetime=new AbortController(),storage={getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)};
const dataProperty=(o,k,value)=>{const d=Object.getOwnPropertyDescriptor(o,k);return !!d&&Object.hasOwn(d,'value')&&d.value===value};
function stamp(b){if(!b)return null;return{bundle:b,world:b.world,story:b.story,host:b.host,definition:b.definition,adapter:b.adapter,revision:readSnapshot(b).revision,position:readSnapshot(b).position,epoch};}
function assertBundle(b,expected){
 if(!b||aborted(b.abort.signal)||!dataProperty(b.world,'story',b.story)||!dataProperty(b.world,'host',b.host)||!dataProperty(b.world,'definition',b.definition)||!dataProperty(b.world,'adapter',b.adapter)||!dataProperty(b.world,'pending',false)||Object.getOwnPropertyDescriptor(b.world,'snapshot'))throw Error('WORLD_SOURCE_CHANGED');
 for(const k of['canOccupy','validLanding','canInteract'])if(!dataProperty(b.host,k,b.hostFns[k]))throw Error('WORLD_HOST_CHANGED');
 if(invoke(storyBusy,b.story)||invoke(pending,b.story))throw Error('WORLD_PENDING');const s=readSnapshot(b);if(expected&&(s.revision!==expected.revision||['scene','x','y','facing'].some(k=>s.position[k]!==expected.position[k])))throw Error('WORLD_REVISION_CHANGED');return s;
}
function assertSource(t){if(dead||aborted(lifetime.signal)||epoch!==t.epoch||current!==t.bundle)throw Error('ENTRY_SUPERSEDED');if(t.bundle)assertBundle(t.bundle,t)}
function sourceToken(){return current?stamp(current):{bundle:null,epoch}}
function report(e,{installed=false}={}){ready=false;lastOperation={status:installed?'INSTALLED_PRESENTATION_HELD':'BLOCKED',error:String(e?.message??e),possibleStorageWrite:e?.possibleStorageWrite===true||!!current?.story.pendingCommit,pendingStorageOutcome:current?.story.pendingCommit?'UNRESOLVED_RETRY_SAME_DRAFT':null};status.textContent=JSON.stringify(lastOperation);update()}
function update(){const b=current,c=b?.cadence?.status(),s=b?readSnapshot(b):null;for(const el of document.querySelectorAll('[data-field]'))el.disabled=dead||busy||!!engine||paused||!ready||!!c?.busy||!!c?.blocked;
 $('#start').disabled=dead||busy||!!b;$('#cold-load').disabled=dead||busy||!!b;$('#continue').disabled=dead||continuePending||(busy&&!engine&&!eventCue)||!paused||!!c?.busy;$('#retry').disabled=dead||(busy&&!engine&&!eventCue)||!b||!!c?.busy;
 $('#cadence-state').textContent=JSON.stringify({profileId:PROFILE.id,profileRevision:PROFILE_REVISION,storagePrefix:PREFIX,ownerOrdinal,liveUnsaved:b?.story.nativeMovementDirty??false,pendingFlush:b?.story.pendingCommit??false,heldCodes:c?.heldCodes??[],acceptedPixels:c?.acceptedPixels??0,paused,inputBlocked:!ready||!!c?.blocked,lastOperation});
 panel?.refresh();$('#t1').disabled=dead||busy||paused||!ready||!b||!b.world.nearby().some(p=>p.id==='trainer:GYM_08_SUB_01');
 $('#repeat-purchase').disabled=dead||busy||paused||!ready||!!engine||!lastPurchase||lastPurchase.owner!==b?.world;
 $('#event-state').textContent=JSON.stringify({eventId:activeEvent?.pointId??null,cueId:eventCue?.id??null,paused,awaitingAcknowledgement:!!eventCue&&!eventCue.consumed});
 const near=new Set(b&&!busy?b.world.nearby().map(p=>p.id):[]);if(lastPurchase&&!near.has(lastPurchase.pointId))$('#repeat-purchase').disabled=true;for(const button of document.querySelectorAll('[data-port]'))button.disabled=button.disabled||!near.has(button.dataset.port)||b?.world.definition.points[button.dataset.port]?.mapId!==s?.position.scene;
 for(const el of document.querySelectorAll('[data-semantic]')){const p=b?.world.definition.points[el.dataset.semantic];el.disabled=el.disabled||!near.has(el.dataset.semantic)||p?.mapId!==s?.position.scene;if(p?.kind==='shop'){try{const price=quotePurchase(s,b.world.catalog.itemContract,'ecology_ball',1,{hubId:p.hubId});el.textContent=p.label+' · 생태볼 1개 '+price.cost+' 게임머니'}catch{el.disabled=true}}if(p?.kind==='event')el.textContent=p.label+' · 원본 이야기';if(p?.kind==='trainer')el.textContent=p.label+(s.progress.defeatedTrainers.includes(p.trainerId)?' · 대화':p.id===PROFILE.rival05.point.id?' · 원본 라이벌 대결':' · 아직 대화 불가');if(p?.id===PROFILE.rival05.point.id&&!s.progress.defeatedTrainers.includes(p.trainerId)&&!b.world.story.trainerAvailable(p.trainerId))el.disabled=true;}
 for(const el of document.querySelectorAll('[data-gym7]')){const p=b?.world.definition.points[el.dataset.gym7];el.disabled=el.disabled||!near.has(el.dataset.gym7)||p?.mapId!==s?.position.scene;if(p?.kind==='trainer'&&!s.progress.defeatedTrainers.includes(p.trainerId)&&!b.world.story.trainerAvailable(p.trainerId))el.disabled=true;} for(const el of document.querySelectorAll('[data-gym8]')){const p=b?.world.definition.points[el.dataset.gym8];el.disabled=el.disabled||!near.has(el.dataset.gym8)||p?.mapId!==s?.position.scene;if(p?.kind==='trainer'&&!s.progress.defeatedTrainers.includes(p.trainerId)&&!b.world.story.trainerAvailable(p.trainerId))el.disabled=true;} for(const el of document.querySelectorAll('[data-harbor]')){const p=b?.world.definition.points[el.dataset.harbor];el.disabled=el.disabled||!near.has(el.dataset.harbor)||p?.mapId!==s?.position.scene;if(p?.kind==='trainer'&&!s.progress.defeatedTrainers.includes(p.trainerId)&&!b.world.story.trainerAvailable(p.trainerId))el.disabled=true;} for(const el of document.querySelectorAll('[data-gym8]')){const p=b?.world.definition.points[el.dataset.gym8];el.disabled=el.disabled||!near.has(el.dataset.gym8)||p?.mapId!==s?.position.scene;if(p?.kind==='trainer'&&!s.progress.defeatedTrainers.includes(p.trainerId)&&!b.world.story.trainerAvailable(p.trainerId))el.disabled=true;}


 const stage=s&&b.world.story.contract.stages.S8,eligible=!!stage&&s.progress.currentStage==='S8'&&stage.completionEnabled&&stage.eventIds.every(id=>s.progress.completedEvents.includes(id))&&stage.requiredTrainerIds.every(id=>s.progress.defeatedTrainers.includes(id));$('#complete-s8').disabled=$('#complete-s8').disabled||!eligible;$('#stage-state').textContent=JSON.stringify({stageId:'S8',eligible,completed:s?.progress.completedStages.includes('S8')??false,noS9Warp:true});
 $('#economy-state').textContent=s?JSON.stringify({money:s.economy.money,ecologyBall:s.inventory.ecology_ball??0,lastHub:s.economy.lastHub,lastReceipt:lastPurchase?.owner===b?.world?lastPurchase.request.transactionId:null}):'';
}
function presentEventCue(){const row=eventCue,box=$('#dialogue');try{box.replaceChildren();if(!row||row.consumed||!row.valid)return;const title=document.createElement('p'),text=document.createElement('p'),next=document.createElement('button');title.textContent='원본 이야기 · '+row.operation.pointId;text.textContent=row.text;next.textContent='확인하고 계속';const revision=row.revision;next.disabled=dead||paused||document.hidden||activeEvent!==row.operation||current?.world!==row.operation.owner;next.dataset.eventAck=String(row.id);next.onclick=()=>{const visible=!document.hidden;if(!visible||dead||paused||eventCue!==row||row.consumed||!row.valid||row.revision!==revision||activeEvent!==row.operation||current?.world!==row.operation.owner)return;row.consumed=true;eventCue=null;const done=row.resolve;row.resolve=null;done();try{next.disabled=true;box.replaceChildren();update()}catch{ready=false}};box.append(title,text,next)}catch(error){status.textContent='이야기 화면을 준비하지 못했습니다. 화면 재시도로 같은 대화를 다시 표시하세요.';ready=false}}
function deferEventDialogue(owner,op){if(!activeEvent||activeEvent.owner!==owner)return;const operation=activeEvent;return new Promise(resolve=>{const row={id:++cueSerial,operation,resolve,revision:0,consumed:false,valid:false,text:''};eventCue=row;try{const descriptor=Object.getOwnPropertyDescriptor(op,'text');if(!descriptor||!Object.hasOwn(descriptor,'value')||typeof descriptor.value!=='string')throw Error('ORIGINAL_DIALOGUE_TEXT');row.text=descriptor.value;row.valid=true;presentEventCue();update()}catch(error){ready=false;status.textContent='원본 이야기 화면이 보류되었습니다. 이 대화는 아직 확인되지 않았습니다.'}})}
function battleView(){return engine?{phase:paused?'combat-paused':engine.snapshot().phase==='ended'?'combat-ended':'combat',battle:engine.snapshot(),battleId:String(battleId),revision:battleRevision,fieldLocked:true,pending:!!mountPending}:null}
async function mountBattleImpl(){if(dead||!engine||!current||battleOwner!==current.world)throw Error('NO_CURRENT_BATTLE');const original=engine,owner=battleOwner,id=battleId,revision=battleRevision,prepared=await prepareT1FrontScene(original.snapshot());if(dead||engine!==original||current?.world!==owner||battleId!==id||battleRevision!==revision){prepared.dispose();throw Error('STALE_BATTLE_ART')}panel?.dispose();scene?.dispose();scene=prepared;panel=mountT1BattlePanel({root:$('#battle'),catalog:current.world.catalog,getView:battleView,onCommand:async(action,stamp)=>{if(dead||paused||document.hidden||engine!==original||current?.world!==owner||stamp.battleId!==String(id)||stamp.expectedRevision!==battleRevision)throw Error('STALE_BATTLE_COMMAND');original.act(action);battleRevision++;try{panel.refresh();panel.draw(performance.now())}finally{if(original.snapshot().phase==='ended'){const done=finishBattle;finishBattle=null;done?.()}}},drawScene:(ctx,s,now)=>scene.draw(ctx,s,now),onError:report});panel.draw(performance.now());if(paused)panel.pause()}
function mountBattle(){if(mountPending)return mountPending;mountPending=mountBattleImpl().finally(()=>{mountPending=null;update()});update();return mountPending}
async function battleDriver(b){if(dead||!current)throw Error('NO_BATTLE_OWNER');engine=b;battleOwner=current.world;battleId++;battleRevision++;ready=false;update();const completion=new Promise(resolve=>{finishBattle=resolve});try{await mountBattle()}catch(e){report(e)}await completion;panel?.dispose();panel=null;scene?.dispose();scene=null;engine=null;battleOwner=null;}
function release(b){if(!b)return;const errors=[];for(const fn of[()=>b.abort.abort(),()=>b.cadence?.dispose(),()=>b.native.dispose(),()=>b.t1Abort.abort(),()=>b.t1.dispose(),()=>b.grid.dispose(),()=>b.exchange.dispose(),()=>b.world.dispose()])try{fn()}catch(e){errors.push(String(e?.message??e))}return errors}
function createBundle(runtime){let world,store,native,grid,exchange;const abort=new AbortController();try{
 world=new CanonicalWorld({adapter,runtime,selectedNative:true,selectedGeometry:geometry,nativeCadence:true,mode:'test',battleDriver,hooks:{dialogue:op=>deferEventDialogue(world,op)},persist:s=>{store.save('SLOT_1',s);return true}});store=createWorldStore(storage,world.catalog,world.host);native=createSelectedWorldPresentation({world,signal:abort.signal});grid=createOriginalGridReturnPresentation({world,signal:abort.signal});exchange=createExperimentalExchange({world,storage});const t1Abort=new AbortController(),t1=createSelectedT1Host({world,signal:t1Abort.signal,context:ctx});const b={world,store,native,grid,exchange,t1,t1Abort,abort,story:world.story,host:world.host,definition:world.definition,adapter:world.adapter,cadence:null,hostFns:{canOccupy:world.host.canOccupy,validLanding:world.host.validLanding,canInteract:world.host.canInteract}};return b;
 }catch(e){abort.abort();native?.dispose();grid?.dispose();exchange?.dispose();world?.dispose();throw e}}
function bridge(b){return isNative(readSnapshot(b))?b.native:b.grid}
async function prepareFrame(b,context,guard){const p=bridge(b);await p.prepare();guard();const frame=p.draw(context);guard();if(!frame.nativeReady&&!frame.gridReady)throw Error('FRAME_REQUIRED');return frame}
async function render(){const b=current,t=sourceToken();if(!b)throw Error('NO_WORLD');if(!isSelectedGeometry(geometry))throw Error('SELECTED_GEOMETRY_DIED');ready=false;update();const frame=(await b.t1.render()).frame;assertSource(t);if(!isSelectedGeometry(geometry))throw Error('SELECTED_GEOMETRY_DIED');lastFrame=frame;ready=true;status.textContent=JSON.stringify({map:readSnapshot(b).position.scene,position:readSnapshot(b).position,revision:readSnapshot(b).revision,ownerOrdinal,frame:frame.status});update();return true}
function bindCadence(b){const wrappers=new Map(),events={addEventListener(type,fn){const wrap=e=>{if((engine||(busy&&!b.story.nativeMovementDirty))&&['blur','pagehide'].includes(type))return;if(type==='keyup'&&(engine||!b.cadence?.status().heldCodes.includes(e.code)))return;if(type==='keydown'&&(b!==current||!ready||busy||paused||!isNative(readSnapshot(b))))return;fn(e);update()};wrappers.set(fn,{type,wrap});window.addEventListener(type,wrap)},removeEventListener(type,fn){const row=wrappers.get(fn);if(row){window.removeEventListener(row.type,row.wrap);wrappers.delete(fn)}}},dw=new Map(),doc={get hidden(){return document.hidden},addEventListener(type,fn){const wrap=e=>{if(!engine&&!(busy&&!b.story.nativeMovementDirty))fn(e)};dw.set(fn,wrap);document.addEventListener(type,wrap)},removeEventListener(type,fn){const wrap=dw.get(fn);if(wrap)document.removeEventListener(type,wrap);dw.delete(fn)}};
 b.cadence=mountHeldNativeCadence({world:b.world,events,document:doc,requestFrame:fn=>window.requestAnimationFrame(fn),cancelFrame:id=>window.cancelAnimationFrame(id),onFrame:async()=>{if(current!==b)throw Error('OLD_CADENCE');return render()},onError:e=>{if(current===b&&!dead)report(e)}})}
function checkSlot(observation){if(observation&&storage.getItem(observation.key)!==observation.raw)throw Error('SLOT_CHANGED_DURING_PREPARATION')}
async function install(runtime,{observation=null,source=sourceToken()}={}){
 assertSource(source);const candidate=createBundle(runtime),expected=stamp(candidate),scratch=document.createElement('canvas');scratch.width=1280;scratch.height=720;let installed=false;
 try{await prepareFrame(candidate,scratch.getContext('2d'),()=>{assertSource(source);assertBundle(candidate,expected);checkSlot(observation)});
  // All callback-capable slot/resource reads precede final intrinsic private-state checks.
  checkSlot(observation);if(!isSelectedGeometry(geometry))throw Error('SELECTED_GEOMETRY_DIED');const cs=readSnapshot(candidate);if(isNative(cs)&&!nativeSafe(cs,cs.position.x,cs.position.y,candidate.host))throw Error('SELECTED_TARGET_UNSAFE');
  assertBundle(candidate,expected);assertSource(source);if(aborted(candidate.abort.signal))throw Error('CANDIDATE_ABORTED');
  const old=current;current=candidate;epoch++;ownerOrdinal++;installed=true;$('#message').textContent='';ready=false;bindCadence(candidate);const cleanupErrors=[];try{candidate.native.dispose()}catch(error){cleanupErrors.push('SCRATCH_NATIVE_CLEANUP: '+String(error?.message??error))}cleanupErrors.push(...(release(old)??[]));lastOperation={status:'INSTALLED',generation:observation?.generation??null,cleanupErrors};
  await render();if(dead||paused||document.hidden)throw Error('INSTALLED_PAUSED');if(cleanupErrors?.length){ready=false;lastOperation={...lastOperation,status:'INSTALLED_CLEANUP_HELD'};update()}
 }catch(e){if(!installed)release(candidate);else report(e,{installed:true});throw e}finally{scratch.width=0;scratch.height=0}
}
function observeLoaded(store,catalog,slot,state){const key=PREFIX+store.keys(slot).primary,raw=storage.getItem(key);if(raw===null)throw Error('NO_PRIMARY_RECORD');const decoded=decodeSlot(raw,slot,{canonicalCatalog:catalog});if(stableJSON(decoded.runtime)!==stableJSON(state))throw Error('LOADED_RECORD_CHANGED');return{key,raw,generation:decoded.generation}}
async function loadSlot(slot){const t=sourceToken(),b=current,s=b.store.load(slot);if(!s)throw Error('NO_COMPLETED_SAVE');const observation=observeLoaded(b.store,b.world.catalog,slot,s);assertSource(t);await install(s,{source:t,observation})}
const read=folder=>async file=>{const r=await fetch(new URL('../native_world_selected_s8_union_r1/source/data/'+folder+'/'+file,import.meta.url));if(!r.ok)throw Error('DATA_HTTP');return new TextDecoder('utf-8',{ignoreBOM:true,fatal:true}).decode(await r.arrayBuffer())};
async function bootstrap(load,fixturePath='fixture.json'){const t=sourceToken();adapter??=await loadApprovedLatestRuntimeAdapter({historicalOptions:{readText:read('canonical-handoff-v1')},stagedOptions:{readStaging:read('staging-20260927')}});assertSource(t);geometry??=await prepareSelectedGeometry({signal:lifetime.signal});assertSource(t);const r=await fetch('./'+fixturePath);if(!r.ok)throw Error('FIXTURE_HTTP');const fixture=await r.json();assertSource(t);const probe=new CanonicalWorld({adapter,runtime:fixture,selectedNative:true,selectedGeometry:geometry,mode:'test'});try{
 const store=createWorldStore(storage,probe.catalog,probe.host);const occupied=Object.values(store.keys('SLOT_1')).some(k=>storage.getItem(PREFIX+k)!==null);assertSource(t);
 if(!load&&occupied)throw Error('기존 저장을 덮어쓰지 않습니다. 저장된 실험 이어하기를 선택하세요.');
 if(load){const saved=store.load('SLOT_1');if(!saved)throw Error('읽을 수 있는 완료 저장이 없습니다.');const observation=observeLoaded(store,probe.catalog,'SLOT_1',saved);assertSource(t);await install(saved,{source:t,observation})}else await install(fixture,{source:t});
 }finally{probe.dispose()}}
function lifecycleGuard(b,e){if(dead||current!==b||epoch!==e||document.hidden)throw Error('ENTRY_SUPERSEDED')}

async function run(fn){if(dead||busy||engine||paused||current?.cadence.status().busy)return;const b=current,e=epoch;busy=true;ready=false;update();try{if(b)await b.cadence.barrier();lifecycleGuard(b,e);if(paused)throw Error('ENTRY_PAUSED');await fn();if(dead||paused||document.hidden)throw Error('ENTRY_PAUSED');if(current){if(lastOperation?.status==='INSTALLED_CLEANUP_HELD')throw Error('INSTALLED_CLEANUP_HELD');await render()}}catch(e){if(!['INSTALLED_PRESENTATION_HELD','INSTALLED_CLEANUP_HELD'].includes(lastOperation?.status))report(e)}finally{busy=false;update()}}
$('#start').onclick=()=>run(()=>bootstrap(false));$('#cold-load').onclick=()=>run(()=>bootstrap(true));
for(const rule of PROFILE.ports){const b=document.createElement('button');b.dataset.port=rule.pointId;b.setAttribute('data-field','');b.textContent=rule.id+' · '+rule.originalCanonical.point.label;b.onclick=()=>ready&&run(()=>current.world.interact(rule.pointId));$('#ports').append(b)}
for(const row of PROFILE.semanticPoints){const el=document.createElement('button');el.dataset.semantic=row.point.id;el.setAttribute('data-field','');el.textContent=row.point.label+(row.point.kind==='heal'?' · 회복만':row.point.kind==='trainer'?' · 대화':' · 생태볼 1개');el.onclick=()=>ready&&run(async()=>{const b=current,p=b.world.definition.points[row.point.id];let request;if(p.id===PROFILE.rival05.point.id&&!readSnapshot(b).progress.defeatedTrainers.includes(p.trainerId))return challengePoint(p.id);if(p.kind==='heal')request={type:'heal',transactionId:'ui-heal-'+crypto.randomUUID()};else if(p.kind==='shop'){const quote=quotePurchase(readSnapshot(b),b.world.catalog.itemContract,'ecology_ball',1,{hubId:p.hubId});request={type:'purchase',transactionId:'ui-purchase-'+crypto.randomUUID(),itemId:'ecology_ball',quantity:1};lastPurchase={owner:b.world,pointId:p.id,request,quote}}else request={type:p.kind==='event'?'event':'talk'};let out;if(p.kind==='event'){const operation={id:++eventSerial,pointId:p.id,owner:b.world};activeEvent=operation;try{out=await b.world.interact(p.id,request)}finally{if(activeEvent===operation){activeEvent=null;if(eventCue?.operation===operation){eventCue.revision++;eventCue=null;$('#dialogue').replaceChildren()}}}}else out=await b.world.interact(p.id,request);lastOperation={status:p.kind==='event'?(out?.alreadyCompleted?'EVENT_ALREADY_COMPLETED':'EVENT_COMPLETED'):p.kind==='trainer'?'READ_ONLY_TALK':p.kind==='heal'?'HEAL_COMPLETED':'PURCHASE_COMPLETED',pointId:p.id,transactionId:request.transactionId??null};$('#message').textContent=out?.message??(p.kind==='event'?(out?.alreadyCompleted?'이미 완료한 이야기입니다.':'원본 이야기 결과가 저장되었습니다.'):p.kind==='heal'?'회복이 완료되었습니다.':'원본 구매 결과가 저장되었습니다.');});$('#semantics').append(el)}
$('#repeat-purchase').onclick=()=>ready&&run(async()=>{const b=current,r=lastPurchase;if(!r||r.owner!==b.world)throw Error('STALE_PURCHASE_RECEIPT');await b.world.interact(r.pointId,r.request);lastOperation={status:'SAME_RECEIPT_REPLAY_COMPLETED',transactionId:r.request.transactionId};$('#message').textContent='같은 구매 요청을 확인했습니다. 중복 구매 효과는 추가하지 않습니다.'});
