  if(!Number.isFinite(now)){fail(Error('CADENCE_TIME'));return}const raw=last===null?0:Math.max(0,now-last);last=now;const dt=Math.min(raw,50);stats.droppedMs+=raw-dt;
  if(busy){stats.pendingFrames++;stats.droppedMs+=dt;schedule();return}
  const next=choose();if(next!==direction){direction=next;fraction=0}const distance=192*dt/1000+fraction,n=Math.floor(distance+1e-10);fraction=distance-n;
  if(!n){schedule();return}const [sx,sy]=V[next];busy=true;schedule();operation=(async()=>{
   const out=await world.moveNativeLive(sx*n,sy*n);stats.acceptedPixels+=out.accepted;if(out.blocked)fraction=0;await draw();
  })().catch(e=>{if(!dead)fail(e)}).finally(()=>{busy=false;schedule()});
 }
 async function barrier(action=()=>undefined,{retry=false}={}){
  if(dead)throw Error('CADENCE_DISPOSED');if(barrierPromise)throw Error('CADENCE_BARRIER_BUSY');clear();busy=true;
  const pending=operation;barrierPromise=(async()=>{await pending;if(dead)throw Error('CADENCE_DISPOSED');
   if(world.story.pendingCommit){if(!retry)throw Error('CADENCE_PENDING_RETRY_REQUIRED');await world.story.retryCommit();world.syncField(true)}
   else await world.flushNativeMovement();
   if(dead)throw Error('CADENCE_DISPOSED');const result=await action();if(dead)throw Error('CADENCE_DISPOSED');await draw();blocked=false;return result;
  })();try{return await barrierPromise}catch(e){if(!dead)fail(e);throw e}finally{barrierPromise=null;busy=false}}
 function stop(){clear();if(dead||barrierPromise)return;barrier().catch(()=>{})}
 function down(e){const d=KEY[e.code];if(!d||e.repeat||dead||paused||blocked||barrierPromise||document.hidden||['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName))return;e.preventDefault?.();if(keys.has(e.code))return;keys.set(e.code,{direction:d,order:++sequence});schedule()}
 function up(e){if(!KEY[e.code])return;keys.delete(e.code);if(!keys.size)stop();else{const d=choose();if(d!==direction){direction=d;fraction=0}}}
